def seed_departments_from_existing_data(apps, schema_editor):
    """从现有用户/知识库的部门字段去重后生成 Department 记录。

    保持 User.department 与 KnowledgeBase.department 字符串值不变，仅作为对齐用。
    """
    Department = apps.get_model('users', 'Department')
    User = apps.get_model('users', 'User')
    KnowledgeBase = apps.get_model('knowledge', 'KnowledgeBase')

    names = set()
    for value in User.objects.exclude(department='').values_list('department', flat=True):
        names.add(value.strip())
    for value in KnowledgeBase.objects.exclude(department='').values_list('department', flat=True):
        names.add(value.strip())

    for name in sorted(names):
        if name:
            Department.objects.get_or_create(name=name)


def reverse_seed_departments(apps, schema_editor):
    """回退时清空自动生成的部门记录"""
    Department = apps.get_model('users', 'Department')
    Department.objects.all().delete()


